import { gradeSupportInbox } from "./grade-support.js";
import { sections } from "./data.js";
import { badge, button, emptyState, escapeHtml as e } from "./ui.js";
import { icon } from "./icons.js";
import { subjects } from "./network-analytics.js";
import { demoDate, studentStatus } from "./chairman-data.js";
import { coursesPage } from "./learning.js";
import { panel, table, select, metric, sparkline } from "./chairman.js";
import { sectionViews, sectionReportTypes, sectionFollowupStatuses, sectionScope, sectionFilters, sectionAcademic, sectionAttendance, sectionTeachers,
  sectionCourses, sectionCourseProgress, sectionFollowups, sectionCoverRequests, sectionOverview, visibleSectionReports } from "./section-data.js";

const percent = (value) => Number(value).toFixed(1) + "%";
const mark = (row) => row.count ? percent(row.mean) : "—";
const statusNames = { present: "Present", absent: "Absent", late: "Late", leave: "On leave" };
const outcome = { ready: "Ready for learning", changes_requested: "Updates requested" };
const choices = (values, current) => values.map(([id, name]) => `<option value="${e(id)}" ${String(id) === String(current) ? "selected" : ""}>${e(name)}</option>`).join("");
const field = (label, body) => `<label class="field">${label}${body}</label>`;
const footer = (label) => `<p class="form-error" role="alert" hidden></p><footer class="dialog-actions">${button("Cancel", "close-dialog", { variant: "secondary" })}<button type="submit" class="button primary">${label}</button></footer>`;
const viewLink = (view, text) => `<a class="button secondary compact" href="#section_head/overview/${view}">${text}</a>`;
const heading = (title, description, actions = "") => `<header class="chairman-page-heading"><div><h1>${title}</h1><p>${description}</p></div><div class="chairman-heading-actions">${badge("Sample data", "amber")}${actions}</div></header>`;

function identity(options, scope) {
  const entries = options.state.accounts.flatMap((person) => person.grants.map((grant, index) => ({ person, grant, index }))).filter(({ grant }) => grant.role === "section_head");
  const selected = options.context.account.id + "|" + options.context.account.grants.indexOf(options.context.grant);
  return `<header class="section-identity"><div><span class="chairman-eyebrow">SECTION HEAD WORKSPACE</span><h1>${e(scope.section.name)}</h1><p>${e(scope.branch.school)} · ${scope.grades[0] === 0 ? "Preschool" : "Grades " + scope.grades[0] + "–" + scope.grades.at(-1)}</p></div><label class="principal-demo-account"><span>Demo Section Head</span><span class="select-wrap"><select data-change="account" aria-label="Preview Section Head">${choices(entries.map(({ person, grant, index }) => [person.id + "|" + index, person.name + " · " + options.state.branches.find((branch) => branch.id === grant.branch)?.name + " · " + sections.find((section) => section.id === grant.section)?.name]), selected)}</select>${icon("chevronDown", 14)}</span></label></header>`;
}

function filters(options, scope, kind) {
  const f = options.section;
  let fields = select("Grade", "section-grade", [["all", "All section grades"], ...scope.grades.map((grade) => [grade, grade === 0 ? "Preschool" : "Grade " + grade])], f.grade);
  if (f.grade !== "all" && Number(f.grade) > 0) fields += select("Class", "section-class", [["all", "All classes"], ...["A", "B"].map((letter) => [f.grade + letter, "Class " + f.grade + letter])], f.className);
  if (["academic", "reports"].includes(kind)) fields += select("Assessment subject", "section-subject", subjects.map((subject) => [subject.id, subject.name]), f.subject) +
    select("Assessment term", "section-term", [1, 2, 3].map((term) => [term, "Term " + term]), f.term);
  if (["attendance", "teaching", "reports"].includes(kind)) fields += `<label class="chairman-filter"><span>Reporting date</span><input type="date" aria-label="Reporting date" data-change="section-date" min="2026-10-12" max="${demoDate}" value="${f.date}"></label>`;
  if (["attendance", "reports"].includes(kind)) fields += select("Attendance period", "section-period", [["day", "One school day"], ["week", "Last 5 school days"], ["month", "Last 20 school days"]], f.period);
  return `<div class="chairman-filters section-filters">${fields}</div>`;
}

function followupPanel(options) {
  const items = sectionFollowups(options.state, options.context);
  const people = [{ id: options.context.account.id, name: options.context.account.name }, ...sectionTeachers(options.state, options.context)];
  const rows = items.map((item) => `<tr><td><strong>${e(item.name)}</strong><small>Class ${e(item.className)} · ${e(item.admission)}</small></td><td>${e(people.find((person) => person.id === item.owner)?.name || "Section office")}</td><td>${e(item.due)}</td><td>${badge(sectionFollowupStatuses[item.status], item.status === "resolved" ? "green" : "amber")}</td><td>${button("Update follow-up", "section-followup-edit", { value: item.id, variant: "secondary compact" })}</td></tr>`).join("");
  return panel("Section follow-ups", "Attendance follow-ups, assigned owners and progress saved in this browser", items.length ? table(["Student", "Owner", "Due", "Status", "Action"], rows, "Section follow-ups") : emptyState("checkCircle", "No follow-ups recorded", "Open a student in Attendance to record a follow-up."));
}

function overview(options, scope) {
  const data = sectionOverview(options.state, options.context);
  const rows = scope.grades.map((grade) => {
    const academic = sectionAcademic(options.state, options.context, { grade }), attendance = sectionAttendance(options.state, options.context, { grade });
    return `<tr><td>${grade ? "Grade " + grade : "Preschool"}</td><td>${mark(academic.summary)}</td><td>${attendance.summary.expected ? percent(attendance.summary.rate) : "—"}</td><td>${sectionCourses(options.state, options.context, { grade }).length}</td></tr>`;
  }).join("");
  return heading("Section Overview", "A daily view of learning, attendance and teaching coordination in your section.", viewLink("academic", "Review academics")) +
    `<div class="chairman-metrics">${metric("Sample student attendance", data.attendance.summary.expected ? percent(data.attendance.summary.rate) : "—", "20 Nov · Illustrative section register", "checkCircle")}${metric("Registered students", data.registered, "Actual student records in this prototype", "users", "blue")}${metric("Teachers serving section", data.teachers.length, "Scoped subjects and class/grade appointments", "book")}${metric("Pending follow-ups", data.followups.filter((item) => item.status !== "resolved").length, "Recorded section attendance follow-ups", "clock", "amber")}</div>` +
    `<div class="section-summary-strip"><div><span>Prototype subjects</span><strong>${data.courses.length}</strong></div><div><span>Published materials</span><strong>${data.materials}</strong></div><div><span>Materials marked done</span><strong>${data.completed} / ${data.expected}</strong></div><div><span>Cover requests pending</span><strong>${data.requests.filter((item) => item.status === "pending").length}</strong></div></div>` +
    `<div class="section-attention"><div><h2>Teaching priorities</h2><p>${data.missing} subjects without lecture materials · ${data.teachers.filter((person) => person.status !== "present").length} section teachers unavailable today.</p></div>${viewLink("teaching", "Review teaching")}</div>` +
    `<div class="chairman-two-columns">${panel("Grades in your section", "Term 3 Mathematics averages and today’s attendance are illustrative", table(["Grade", "Average mark", "Attendance", "Prototype subjects"], rows, "Section grade summary"))}${panel("Attendance over five school days", "Section students only · Late arrivals count as present", sparkline(sectionAttendance(options.state, options.context, { period: "week" }).trend, "Section attendance trend"))}</div>` + followupPanel(options);
}

function courseTable(options) {
  const courses = sectionCourses(options.state, options.context, options.section);
  const rows = courses.map((course) => {
    const progress = sectionCourseProgress(options.state, course);
    return `<tr><td><strong>${e(course.title)}</strong><small>Class ${e(course.className)}</small></td><td>${e(progress.teacher)}</td><td>${progress.materials}</td><td>${progress.completed} / ${progress.expected}</td><td>${badge(progress.review ? outcome[progress.review.status] : "Not reviewed", progress.review?.status === "changes_requested" ? "amber" : "neutral")}</td><td><div class="section-row-actions">${button("Materials & progress", "open-course", { value: course.id, variant: "secondary compact" })}${button("Edit assignment", "assign", { value: course.id, variant: "secondary compact" })}${button("Review materials", "section-review", { value: course.id, variant: "secondary compact" })}</div></td></tr>`;
  }).join("");
  return panel("Subjects and lecture progress", "Subjects in the selected grades/class · Subject list is independent of the assessment subject", courses.length ? table(["Subject", "Assigned teacher", "Materials", "Done / assigned", "Review", "Actions"], rows, "Section subjects") : emptyState("book", "No subjects for this selection", "Choose another section grade or class. New subjects have not been created by these sample assessments."));
}

function academic(options, scope) {
  if (sectionCourses(options.state, options.context).some((course) => course.id === options.courseId)) return coursesPage(options);
  const result = sectionAcademic(options.state, options.context, options.section), f = options.section;
  const details = ["classes", "teachers"].includes(f.compare);
  const rows = result.rows.map((row) => `<tr><td>${e(row.name)}</td>${details ? `<td>${e(row.detail || "")}</td>` : ""}<td><strong>${mark(row)}</strong></td><td>${row.count ? percent(row.passRate) : "—"}</td><td>${row.count}</td></tr>`).join("");
  return heading("Academic & Subjects", "Compare results, coordinate subject assignments and review published lecture materials.") + filters(options, scope, "academic") +
    `<div class="chairman-metrics">${metric("Average mark", mark(result.summary), result.subjectName + " · Selected section grades/class", "book")}${metric("Pass rate", result.summary.count ? percent(result.summary.passRate) : "—", result.summary.count + " sample students assessed", "checkCircle", "blue")}${metric("Classes assessed", result.classes.length, "Illustrative assessment cohorts", "users")}${metric("Prototype subjects", sectionCourses(options.state, options.context, f).length, "Assignments within the selected grades/class", "file", "amber")}</div>` +
    panel("Academic comparisons", "Same subject, term and section scope · Sample marks are separate from subject enrolments", `<div class="chairman-panel-filter">${select("Compare by", "section-compare", [["classes", "Classes"], ["grades", "Grades"], ["subjects", "Subjects"], ["teachers", "Assigned teachers"]], f.compare)}</div>` + table([f.compare === "classes" ? "Class" : f.compare === "grades" ? "Grade" : f.compare === "teachers" ? "Teacher" : "Subject", ...(details ? [f.compare === "teachers" ? "Classes" : "Assigned teacher"] : []), "Average", "Pass rate", "Sample assessed"], rows, "Section academic comparison"), button("Comparison CSV", "section-export", { value: "academic", variant: "secondary compact", iconName: "download" })) + courseTable(options);
}

function attendance(options, scope) {
  const result = sectionAttendance(options.state, options.context, options.section), f = options.section;
  const rows = result.classes.map((row) => `<tr><td><button type="button" class="chairman-person-link" data-action="section-attendance-class" data-value="${row.className}">Class ${row.className}</button></td><td>${percent(row.rate)}</td><td>${row.present}</td><td>${row.absent}</td><td>${row.late}</td></tr>`).join("");
  const page = Math.min(f.page, Math.max(1, Math.ceil(result.rows.length / 12))), start = (page - 1) * 12;
  const people = result.rows.slice(start, start + 12).map((student) => `<tr><td><button type="button" class="chairman-person-link" data-action="section-student" data-value="${student.id}">${e(student.name)}</button><small>${e(student.admission)}</small></td><td>Class ${student.className}</td><td>${student.missed}</td><td>${badge(statusNames[student.status], student.status === "present" ? "green" : "amber")}</td></tr>`).join("");
  return heading("Attendance", "Review section registers, repeated absences and class teacher follow-ups.", button("Attendance CSV", "section-export", { value: "attendance", variant: "secondary", iconName: "download" })) + filters(options, scope, "attendance") +
    `<p class="chairman-filter-note">${result.dates[0]} – ${result.dates.at(-1)} · ${result.dates.length} school day(s) · Illustrative students. Period totals count attendance-days; late arrivals are included in present totals.</p>` +
    `<div class="chairman-metrics">${metric("Attendance rate", result.summary.expected ? percent(result.summary.rate) : "—", "Selected section grades/class", "checkCircle")}${metric("Present", result.summary.present, "Out of " + result.summary.expected + " expected attendance-days", "users", "blue")}${metric("Absent", result.summary.absent, "In the selected period", "alert", "amber")}${metric("Late arrivals", result.summary.late, "Included in present totals", "clock")}</div>` +
    `<div class="chairman-two-columns">${panel("Class attendance", "Select a class to open its register", table(["Class", "Rate", "Present", "Absent", "Late"], rows, "Section class attendance", "scroll-table"))}${panel("Attendance trend", "Selected reporting period · Section students only", sparkline(result.trend, "Selected section attendance trend"))}</div>` +
    panel("Student attendance register", "Select a student for their last 20 school days and a follow-up note", `<div class="chairman-list-tools">${select("Attendance watchlist", "section-flag", [["all", "All students"], ["repeated", "3+ absences in 20 days"], ["absent", "Absent on latest day"], ["late", "Late on latest day"]], f.flag)}<label class="chairman-search">${icon("search", 16)}<input type="search" aria-label="Search section student" data-focus="section-search" data-change="section-query" placeholder="Search student or admission" value="${e(f.query)}"></label></div>` + table(["Student", "Class", "Absences in 20 days", "Latest status"], people, "Section student register") +
      `<div class="chairman-pager"><span>${result.rows.length ? start + 1 : 0}–${Math.min(start + 12, result.rows.length)} of ${result.rows.length}</span><div>${button("Previous", "section-page", { value: page - 1, variant: "secondary compact", extra: page <= 1 ? "disabled" : "" })}<span>Page ${page}</span>${button("Next", "section-page", { value: page + 1, variant: "secondary compact", extra: start + 12 >= result.rows.length ? "disabled" : "" })}</div></div>`) + followupPanel(options);
}

function teaching(options, scope) {
  const teachers = sectionTeachers(options.state, options.context, options.section), courses = sectionCourses(options.state, options.context, options.section);
  const query = options.section.teacherQuery.toLowerCase();
  const rows = teachers.filter((person) => (person.name + " " + person.classes.join(" ")).toLowerCase().includes(query)).map((person) => `<tr><td><button type="button" class="chairman-person-link" data-action="section-teacher" data-value="${person.id}">${e(person.name)}</button><small>${person.role}</small></td><td>${e(person.classes.join(", "))}</td><td>${person.courses.length}</td><td>${badge(statusNames[person.status], person.status === "present" ? "green" : "amber")}</td><td>${person.courses.reduce((sum, course) => sum + sectionCourseProgress(options.state, course).materials, 0)}</td></tr>`).join("");
  const courseRows = courses.map((course) => {
    const progress = sectionCourseProgress(options.state, course);
    return `<tr><td><strong>${e(course.title)}</strong><small>Class ${e(course.className)}</small></td><td>${e(progress.teacher)}</td><td>${progress.materials ? progress.materials + " published" : badge("Materials missing", "amber")}</td><td><div class="section-row-actions">${button("Review materials", "section-review", { value: course.id, variant: "secondary compact" })}${button("Request cover", "section-request-cover", { value: course.id, variant: "secondary compact" })}</div></td></tr>`;
  }).join("");
  const requests = sectionCoverRequests(options.state, options.context);
  const requestRows = requests.map((item) => `<tr><td>${e(item.title)}<small>Class ${e(item.className)} · ${e(item.date)}</small></td><td>${e(item.reason)}</td><td>${badge(item.status === "fulfilled" ? "Cover assigned" : item.status === "declined" ? "Declined" : "Awaiting Vice Principal", item.status === "fulfilled" ? "green" : "amber")}${item.teacherName ? `<small>${e(item.teacherName)}</small>` : ""}${item.decisionNote ? `<small>${e(item.decisionNote)}</small>` : ""}</td></tr>`).join("");
  return heading("Teaching Coordination", "Support the teachers serving your section and request daily cover when needed.") + filters(options, scope, "teaching") +
    `<div class="chairman-metrics">${metric("Section teaching staff", teachers.length, "Selected section grades/class", "users")}${metric("Available", teachers.filter((person) => person.status === "present").length, "Latest school day of reporting date", "checkCircle")}${metric("Subjects without materials", courses.filter((course) => !sectionCourseProgress(options.state, course).materials).length, "Selected section subjects", "file", "amber")}${metric("Pending cover requests", requests.filter((item) => item.status === "pending").length, "Across your assigned section", "clock", "blue")}</div>` +
    gradeSupportInbox(options) + panel("Teachers in your section", "Workloads show only this section’s subjects; shared teachers’ other classes are excluded", `<div class="chairman-list-tools"><label class="chairman-search">${icon("search", 16)}<input type="search" aria-label="Search section teacher" data-change="section-teacher-query" data-focus="section-teacher-search" placeholder="Search teacher or class" value="${e(options.section.teacherQuery)}"></label></div>` + table(["Teacher", "Section classes", "Subjects", "Availability", "Materials"], rows, "Section teaching staff")) +
    panel("Subject readiness and cover", "Cover requests go to the Vice Principal workspace; subject teacher appointments remain unchanged", table(["Subject", "Assigned teacher", "Materials", "Actions"], courseRows, "Section subject coordination")) +
    panel("Your section’s cover requests", "Requests and Vice Principal outcomes are stored in this browser", requests.length ? table(["Subject / date", "Request reason", "Outcome"], requestRows, "Section cover requests") : emptyState("book", "No cover requested", "Choose Request cover against a subject to record a request for the Vice Principal."));
}

export function sectionReportPreview(report) {
  return `<article class="executive-report-preview section-report-preview"><header><span class="chairman-eyebrow">${e(report.owner.school)} · ${e(report.owner.sectionName)}</span><h2>${e(report.title)}</h2><p>${e(report.criteria.from)} – ${e(report.criteria.to)} · ${report.criteria.grades.map((grade) => grade ? "Grade " + grade : "Preschool").join(", ")}${report.criteria.className !== "all" ? " · Class " + e(report.criteria.className) : ""}</p>${badge("SAMPLE DATA · PROTOTYPE", "amber")}</header><div class="executive-report-stats"><div><span>Subject average</span><strong>${mark(report.summary.academic)}</strong></div><div><span>Sample attendance</span><strong>${report.summary.attendance.expected ? percent(report.summary.attendance.rate) : "—"}</strong></div><div><span>Prototype subjects</span><strong>${report.summary.courses}</strong></div><div><span>Teaching staff</span><strong>${report.summary.teachers}</strong></div></div><p class="executive-report-criteria">Academic sample: ${e(report.criteria.subject)} · Term ${report.criteria.term} · Comparison by ${e(report.criteria.comparison)}. Attendance covers ${report.criteria.schoolDays} school day(s); late arrivals count as present. Assessments and registers are illustrative; course/material counts come from prototype records.</p>${table(report.customColumns.map(([, label]) => label), report.customRows.map((row) => '<tr>' + report.customColumns.map(([key]) => `<td>${e(row[key])}</td>`).join("") + '</tr>').join(""), report.owner.role === "class_teacher" ? "Generated class report" : report.owner.role === "coordinator" ? "Generated grade report" : "Generated section report")}${report.type === "brief" && report.followups.length ? `<h3 class="section-report-followup-heading">Recorded attendance follow-ups</h3>${table(["Student", "Class", "Due", "Status"], report.followups.map((item) => `<tr><td>${e(item.name)}</td><td>${e(item.className)}</td><td>${e(item.due)}</td><td>${e(sectionFollowupStatuses[item.status])}</td></tr>`).join(""), "Section report follow-ups")}` : ""}<footer>Generated ${e(new Intl.DateTimeFormat("en-GB", { dateStyle: "medium", timeStyle: "short", timeZone: "Asia/Colombo" }).format(new Date(report.generatedAt)))} · Sri Lanka time. ${report.owner.role === "class_teacher" ? "Class Teacher" : report.owner.role === "coordinator" ? "Grade Coordinator" : "Section Head"}: ${e(report.owner.name)}. Sample data for client demonstration.</footer></article>`;
}

function reports(options, scope) {
  const f = options.section, history = visibleSectionReports(options.state, options.context), current = history.find((item) => item.id === f.reportId);
  return heading("Section Reports", "Capture section academic, attendance and teaching progress for senior leadership.") +
    `<div class="section-report-builder surface"><div>${select("Report type", "section-report-type", Object.entries(sectionReportTypes), f.reportType)}${f.reportType === "academic" ? select("Comparison", "section-compare", [["classes", "Classes"], ["grades", "Grades"], ["subjects", "Subjects"], ["teachers", "Assigned teachers"]], f.compare) : ""}</div>${filters(options, scope, "reports")}<div class="section-report-generate"><p>${icon("school", 17)}${e(scope.branch.name)} · ${e(scope.section.name)} only</p>${button("Generate section report", "section-generate-report", { iconName: "file" })}</div></div>` +
    `<section class="surface chairman-report-result"><div class="chairman-report-actions">${current ? select("Download format", "section-report-format", [["csv", "CSV spreadsheet"], ["html", "Standalone HTML"]], f.reportFormat) + button("Download report", "section-download-report", { value: current.id, variant: "secondary", iconName: "download" }) + button("Print / Save PDF", "section-print-report", { value: current.id, variant: "secondary", iconName: "file" }) : "Report preview"}</div>${current ? sectionReportPreview(current) : emptyState("file", "Your section report starts here", "Choose a report and filters, then generate a snapshot to preview, download or print.")}</section>` +
    panel("Saved section snapshots", "Latest eight snapshots for this school and section; changing filters does not modify saved reports", `<div class="chairman-report-history">${history.map((item) => `<button type="button" class="chairman-history-card ${item.id === current?.id ? "is-selected" : ""}" data-action="section-open-report" data-value="${item.id}">${icon("file", 20)}<span><strong>${e(item.title)}</strong><small>${e(item.criteria.to)} · ${item.customRows.length} rows · ${e(item.owner.sectionName)}</small></span>${badge("Sample", "neutral")}</button>`).join("") || '<p class="chairman-no-history">Generated section reports will appear here.</p>'}</div>`);
}

export function sectionHeadPage(options) {
  const scope = sectionScope(options.state, options.context);
  if (!scope) return emptyState("school", "No section assigned", "A school and academic section appointment is required.");
  const view = options.section.view;
  return `<section class="chairman-portal section-portal">${identity(options, scope)}<nav class="chairman-view-bar section-view-bar" aria-label="Section Head views">${sectionViews.map((item) => `<a href="#section_head/overview/${item.id}" aria-label="${item.name}" ${item.id === view ? 'aria-current="page" class="is-active"' : ""}>${icon(item.icon, 18)}<span class="chairman-view-full">${item.name}</span><span class="chairman-view-short">${item.short}</span></a>`).join("")}</nav><div class="chairman-analytics section-analytics">${({ summary: overview, academic, attendance, teaching, reports })[view](options, scope)}</div></section>`;
}

export function sectionStudentPanel(options, student, followupAction = "section-followup-new") {
  const result = sectionAttendance(options.state, options.context, options.section);
  return `<div class="chairman-person-heading"><h3>${e(student.name)}</h3><p>${e(student.admission)} · Class ${student.className}</p>${badge("Illustrative student", "amber")}</div><p class="chairman-filter-note">Last 20 school days ending ${result.repeat.at(-1)}</p><div class="chairman-attendance-calendar">${result.repeat.map((date) => { const status = studentStatus(student, date, options.state); return `<div class="${status}"><span>${date}</span><strong>${statusNames[status]}</strong></div>`; }).join("")}</div><footer class="dialog-actions">${button("Record attendance follow-up", followupAction, { value: student.id, iconName: "edit" })}</footer>`;
}

export function sectionFollowupForm(options, student, previous) {
  const people = [...new Map([{ id: options.context.account.id, name: options.context.account.name }, ...sectionTeachers(options.state, options.context)].map((person) => [person.id, person])).values()];
  return `<form data-form="${options.context.role === "coordinator" ? "grade-followup" : "section-followup"}"><div class="form-body"><input type="hidden" name="id" value="${e(previous?.id || "")}"><input type="hidden" name="student" value="${e(student.id)}"><h3>${e(student.name)} · Class ${e(student.className)}</h3>${field("Follow-up owner", `<select name="owner">${choices(people.map((person) => [person.id, person.name]), previous?.owner || options.context.account.id)}</select>`)}${field("Follow-up status", `<select name="status">${choices(Object.entries(sectionFollowupStatuses), previous?.status || "open")}</select>`)}${field("Due date", `<input type="date" name="due" required min="${demoDate}" max="2026-11-27" value="${e(previous?.due || demoDate)}">`)}${field("Follow-up note", '<textarea name="note" rows="3" maxlength="1000" required placeholder="Record the next step or meeting outcome"></textarea>')}${previous ? '<div class="vice-note-history"><h3>Previous notes</h3>' + previous.notes.map((note) => `<article><p>${e(note.text)}</p><small>${e(note.by)} · ${e(note.at.slice(0, 10))}</small></article>`).join("") + '</div>' : ""}<p class="chairman-filter-note">An owner is recorded in this browser for coordination.</p></div>${footer(options.context.role === "coordinator" ? "Save grade follow-up" : "Save section follow-up")}</form>`;
}

export function sectionReviewForm(options, course) {
  const review = options.state.sectionCourseReviews?.[course.id];
  return `<form data-form="section-review"><div class="form-body"><input type="hidden" name="course" value="${course.id}"><h3>${e(course.title)} · Class ${e(course.className)}</h3>${field("Material review outcome", `<select name="status">${choices(Object.entries(outcome), review?.status || "ready")}</select>`)}${field("Review note for teacher", `<textarea name="note" maxlength="1000" rows="4" required>${e(review?.note || "")}</textarea>`)}<p class="chairman-filter-note">The assigned teacher can see this review in their subject workspace.</p></div>${footer("Save material review")}</form>`;
}

export function sectionCoverRequestForm(course) {
  return `<form data-form="section-cover-request"><div class="form-body"><input type="hidden" name="course" value="${course.id}"><h3>${e(course.title)} · Class ${e(course.className)}</h3>${field("Cover date", `<input name="date" type="date" readonly value="${demoDate}">`)}${field("Reason for cover", '<textarea name="reason" maxlength="500" rows="4" required placeholder="Explain why temporary cover is needed"></textarea>')}<p class="chairman-filter-note">The Vice Principal assigns the temporary teacher from their workspace. This records a request in the demo.</p></div>${footer("Request temporary cover")}</form>`;
}

export function sectionTeacherPanel(options, teacher) {
  return `<div class="chairman-person-heading"><h3>${e(teacher.name)}</h3><p>${e(teacher.role)} · ${e(teacher.classes.join(", "))}</p>${badge(statusNames[teacher.status], teacher.status === "present" ? "green" : "amber")}</div>${panel(options.context.role === "coordinator" ? "Subjects in this grade" : "Subjects in this section", "Only your appointed academic scope is included", table(["Subject", "Class", "Materials", "Completion"], teacher.courses.map((course) => { const p = sectionCourseProgress(options.state, course); return `<tr><td>${e(course.title)}</td><td>${e(course.className)}</td><td>${p.materials}</td><td>${p.completed} / ${p.expected}</td></tr>`; }).join(""), options.context.role === "coordinator" ? "Teacher grade workload" : "Teacher section workload"))}`;
}

export function sectionReportHTML(report, logo = "") {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${e(report.title)} · SAMPLE · Sussex College Network</title><style>@page{size:A4 landscape;margin:14mm}*{box-sizing:border-box}body{font:14px/1.6 Arial,sans-serif;max-width:1180px;margin:30px auto;padding:0 20px;color:#18382c}h2{font-size:28px}header{padding:20px 0}.export-brand{display:flex;align-items:center;gap:18px;border-bottom:3px solid #1b6752}.export-brand img{width:65px;height:80px;object-fit:contain}.executive-report-stats{display:grid;grid-template-columns:repeat(4,1fr);background:#edf5ee;padding:20px;gap:15px}.executive-report-stats span,.executive-report-stats strong{display:block}.executive-report-stats strong{font-size:26px}.badge{display:inline-block;background:#fff3d1;padding:4px 8px;font-size:12px}table{border-collapse:collapse;width:100%;font-size:12px}th,td{text-align:left;border-bottom:1px solid #dce7dc;padding:9px}th{background:#edf5ee}tr{break-inside:avoid}thead{display:table-header-group}.executive-report-criteria,footer{font-size:12px;color:#52685b}footer{margin-top:22px;border-top:1px solid #dce7dc;padding-top:15px}@media print{body{margin:0;padding:0}.executive-report-stats{print-color-adjust:exact}}</style></head><body><header class="export-brand">${logo ? `<img src="${e(logo)}" alt="Sussex College Network logo">` : ""}<div><strong>Sussex College Network</strong><p>${report.owner.role === "class_teacher" ? "Class Teacher’s office · Class " + e(report.owner.className) : report.owner.role === "coordinator" ? "Grade Coordinator’s office · Grade " + e(report.owner.grade) : "Section Head’s office · " + e(report.owner.sectionName)}</p></div></header>${sectionReportPreview(report)}</body></html>`;
}
